mapper.select:
SELECT ai.*
FROM approval_instance ai
WHERE ai.resource_id = #{resourceId}
  AND ai.type = #{formKey}
  AND EXISTS (
      SELECT 1 FROM approval_flow_version afv
      WHERE afv.id = ai.flow_version_id AND afv.organization_id = #{organizationId}
  )
ORDER BY ai.submit_time DESC, ai.id DESC
LIMIT 1
FOR UPDATE

SELECT ai.*
FROM approval_instance ai
INNER JOIN approval_flow_version afv ON afv.id = ai.flow_version_id
WHERE ai.resource_id = #{resourceId}
  AND afv.organization_id = #{organizationId}
ORDER BY ai.submit_time DESC, ai.id DESC

SELECT approval_status AS approvalStatus, approved, create_user AS createUser,

    NULL AS owner
    owner

FROM ${sourceTable}
WHERE id = #{id} AND organization_id = #{organizationId}

    AND custom_form_id = #{formKey}

FOR UPDATE
